import { copyFile, mkdir, symlink } from "fs/promises";
import { resolve, join as join2 } from "path";
import { parseArgs } from "util";

// e2e/install-check/contract.ts
var TURN_END = "soroi-install-check:turn-end";
var WORKER_NAME = "InstallCheckWorker";
var PROBE_CALL = "const install_output = install_check_double(install_input)";
var PROBE_CODE = `const install_input = 21
${PROBE_CALL}
stop(install_output)`;
function initialPrompt() {
  const workerTask = "Read-only installation check. Do not edit files or call soroi_eval. Call soroi_return once with result install-check-complete, then end your turn.";
  return `This is a bounded installation check, not a source-editing task. Read skill://soroi-eval first. Then call soroi_eval exactly with ${JSON.stringify({ mode: "dry_run", code: PROBE_CODE })}. Do not use formal mode, pins or env. Next call soroi_task with ${JSON.stringify({ context: "Read-only installation check; no source edits or formal eval.", tasks: [{ name: WORKER_NAME, agent: "soroi-worker", task: workerTask }] })}. Wait for the actual worker handback before reporting the real tool results. Do not edit files.`;
}

// e2e/install-check/registration.ts
import { realpath } from "fs/promises";
import { join } from "path";

// e2e/standin/evidence.ts
function object(value) {
  if (value === null || typeof value !== "object" || Array.isArray(value))
    throw new Error("Expected an object");
  return value;
}
function text(value) {
  if (typeof value !== "string")
    throw new Error("Expected a string");
  return value;
}
function list(value) {
  if (!Array.isArray(value))
    throw new Error("Expected an array");
  return value;
}

// e2e/install-check/registration.ts
async function registeredPackage(home) {
  const argv = [join(home, ".local", "bin", "soroi"), "plugin", "list", "--json"];
  const child = Bun.spawn(argv, { stdin: "ignore", stdout: "pipe", stderr: "pipe" });
  const [code, stdout, stderr] = await Promise.all([
    child.exited,
    new Response(child.stdout).text(),
    new Response(child.stderr).text()
  ]);
  if (code !== 0)
    throw new Error(`Installed plugin query exited ${code}: ${stderr}`);
  const entries = list(object(JSON.parse(stdout)).npm).map(object);
  const selected = entries.filter((entry) => entry.name === "omp-soroi" && entry.enabled === true);
  if (selected.length !== 1)
    throw new Error("The installed registry must select one enabled omp-soroi package");
  return { root: await realpath(text(selected[0].path)), argv, stdout };
}

// e2e/install-check/prepare.ts
async function main() {
  const { values } = parseArgs({ options: {
    home: { type: "string" },
    proof: { type: "string" },
    work: { type: "string" }
  } });
  if (!values.home || !values.proof || !values.work) {
    throw new Error("Usage: bun install-check/prepare.js --home HOME --proof PROOF --work WORK");
  }
  const home = resolve(values.home), proof = resolve(values.proof), work = resolve(values.work);
  const registration = await registeredPackage(home);
  await mkdir(join2(work, "nodes"), { recursive: true });
  await mkdir(join2(work, "node_modules"), { recursive: true });
  await mkdir(proof, { recursive: true });
  await symlink(registration.root, join2(work, "node_modules", "omp-soroi"), "dir");
  await copyFile(join2(import.meta.dir, "probe-node.ts"), join2(work, "nodes", "install_check_double.ts"));
  const observer = join2(import.meta.dir, "observe.ts");
  await Bun.write(join2(proof, "check.yml"), JSON.stringify({
    startup: { setupWizard: false, checkUpdate: false },
    personality: "pragmatic",
    task: { agentIdleTtlMs: 2000 },
    extensions: [observer]
  }, null, 2) + `
`);
  await Bun.write(join2(proof, "prepared.json"), JSON.stringify({
    startedAt: new Date().toISOString(),
    home,
    work,
    observer,
    registration
  }, null, 2) + `
`);
  const prompt = initialPrompt();
  await Bun.write(join2(proof, "recipe.json"), JSON.stringify({
    ompArgs: ["--cwd", work, "--config", join2(proof, "check.yml"), "--", prompt],
    steps: [
      { kind: "expect", pattern: TURN_END },
      { kind: "send", text: "/exit" },
      { kind: "expect", pattern: "/exit" },
      { kind: "send", text: "\r" }
    ]
  }, null, 2) + `
`);
  console.log(JSON.stringify({ phase: "prepared", proof, work, packageRoot: registration.root }));
}
await main();

